using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class ConsistentRatingActualChecks {
 public sealed class Document {public Video video;public CommentSuggestion[] after;}
 public static int Main(string[] args){try{string root=args[0];var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};var doc=json.Deserialize<Document>(File.ReadAllText(Path.Combine(root,"extension/data/replier-grounded-checks/reference-grounding-CFYOk550ckc.json")));var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(doc.video.Id);var rows=doc.after;var before=rows.Select(r=>new{text=r.Text,score=r.FitScore,eligible=r.FitEligible}).ToArray();foreach(var row in rows)row.FitContextKey=null;
 var repeats=new List<object>();bool repeatedStable=true;int calls=0;string target=rows[1].Text;
 var runtimes=DualCommentService.Models.ToDictionary(n=>n,n=>new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),n));var senders=new Dictionary<string,Func<object,CancellationToken,Task<string>>>();
 foreach(string modelName in DualCommentService.Models){string name=modelName;bool repeated=false;senders[name]=async(body,token)=>{calls++;string first=await runtimes[name].Chat(body,token).ConfigureAwait(false);var request=SceneMaterial.Json(json.Serialize(body));var props=CaptionService.Get(CaptionService.Get(request,"format"),"properties");if(CaptionService.Get(props,"connection")!=null&&!repeated){var messages=(object[])CaptionService.Get(request,"messages");var input=SceneMaterial.Json((string)CaptionService.Get(messages.Last(),"content"));if((string)CaptionService.Get(input,"comment")==target){repeated=true;calls++;string second=await runtimes[name].Chat(body,token).ConfigureAwait(false);string a=(string)CaptionService.Get(SceneMaterial.Json(first),"connection"),b=(string)CaptionService.Get(SceneMaterial.Json(second),"connection");repeatedStable&=a==b;repeats.Add(new{model=name,first=a,second=b,independent_model_requests=true});Console.WriteLine("REPEAT "+name+" "+a+" / "+b);}}return first;};}
 bool cacheStable;try{var scoring=new CombinedFitScoring(new FitScoring(runtimes[DualCommentService.Models[0]],senders[DualCommentService.Models[0]]),new FitScoring(runtimes[DualCommentService.Models[1]],senders[DualCommentService.Models[1]]),runtimes[DualCommentService.Models[0]].Unload);scoring.Evaluate(doc.video,content,rows,CancellationToken.None).GetAwaiter().GetResult();int prior=calls;var totals=rows.Select(r=>r.FitScore).ToArray();scoring.Evaluate(doc.video,content,rows,CancellationToken.None).GetAwaiter().GetResult();cacheStable=calls==prior&&rows.Select(r=>r.FitScore).SequenceEqual(totals);}finally{foreach(var model in runtimes.Values.Reverse())model.Dispose();}
 bool[] expected={false,true,true};bool pass=cacheStable&&repeatedStable&&repeats.Count==2;for(int i=0;i<rows.Length;i++){pass&=rows[i].FitEligible==expected[i];Console.WriteLine("RESULT "+before[i].score+" -> "+rows[i].FitScore+" eligible="+rows[i].FitEligible+" "+rows[i].Text);}
 Console.WriteLine("CACHE "+cacheStable);File.WriteAllText(Path.Combine(root,"extension/data/replier-grounded-checks/consistent-rating-CFYOk550ckc.json"),json.Serialize(new{video=doc.video,before=before,after=rows,connection_repeats=repeats,cache_stable=cacheStable,pass=pass,no_new_comments=true}));Console.WriteLine(pass?"PASS categorical consistency, independent repeated relation decisions, valid comments retained and missing name excluded":"FAIL consistency contrast; inspect saved results");return pass?0:1;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
